/** A name the set answers to — the value `feature.icon` stores. */
export type IconName = keyof typeof GLYPHS

/** Every name, in the order the set draws them. */
export const ICON_NAMES = Object.keys(GLYPHS) as IconName[]

export interface IconProps extends Omit<SVGProps<SVGSVGElement>, 'name'> {
  /** Rendered width/height in px. The set draws at 24. */
  size?: number
}

/**
 * One glyph from the set.
 *
 * `currentColor` and no other ink: an icon takes the colour of the copy beside
 * it, so a band that inverts on `ink` inverts its icons with it and no fill
 * ever has to be told what surface it is on. The kit's own exports carry
 * `#232323` and `black` — the same glyph in two hard-coded inks, which is the
 * clearest possible argument for not keeping either.
 *
 * Decorative: a feature's icon repeats what its heading already says, so the
 * accessible name is the heading and this draws nothing for a screen reader.
 */
export function Icon({ name, size = 24, className, ...rest }: IconProps & { name: IconName }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
      focusable="false"
      className={cn('block shrink-0', className)}
      {...rest}
    >
      <path d={GLYPHS[name]} fill="currentColor" />
    </svg>
  )
}

function boundGlyph(name: IconName): ComponentType<IconProps> {
  function Glyph(props: IconProps) {
    return <Icon name={name} {...props} />
  }
  Glyph.displayName = `Icon(${name})`
  return Glyph
}

/**
 * THE SET AS COMPONENTS, keyed by the name an editor stores — the shape both
 * consumers want and neither can build for itself.
 *
 * The feature band resolves a stored name against it, and the canvas hands it
 * to the knob control so the picker draws the glyph rather than listing
 * `file-magnifying-glass`. The knob declaration carries `optionPreview: 'glyph'`
 * and a name and no component, because `@o3/sanity/knobs` is bundled into the
 * Studio and the preview overlay and may not name React (ADR 0020) — so this is
 * where the names become pictures, and `icons.test.ts` is what keeps the two
 * lists the same length.
 *
 * `none` is not in here. An icon nobody drew is the absence of an entry, which
 * is also what an unrecognised name resolves to.
 */
export const ICONS: Readonly<Record<IconName, ComponentType<IconProps>>> = Object.fromEntries(
  ICON_NAMES.map((name) => [name, boundGlyph(name)]),
) as Record<IconName, ComponentType<IconProps>>
